mapper.select:
SELECT aa.* FROM ( SELECT DISTINCT CURVE_CODE id, (SELECT ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE=#{CURVE_CLASS} AND ITEM_CODE=CURVE_TYPE) ||'-'|| (SELECT ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE=#{IRS_CURVE_TYPE} AND ITEM_CODE=CURVE_INT_TYPE) ||'-'|| BASE_INT_CODE ||'-'|| (SELECT ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE=#{PRICE_TYPE} AND ITEM_CODE=PRICE_TYPE) text, CURVE_TYPE, CURVE_INT_TYPE, BASE_INT_CODE, PRICE_TYPE FROM MST_CURVE_DEF
